package com.archos.mediacenter.video.leanback;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import com.archos.mediacenter.video.leanback.PreviewLibraryLoader.*;
import java.util.*;
import org.json.*;

/** Home presentation and explicit row membership. Never changes playback or watched state. */
public final class PreviewHomeRows {
 public static final String[] SYSTEM={"continue","watchnext","recent","trending","popular","watched","similar"};
 private static final String[] LABELS={"Continue Watching","Watch Next","Recently Added","Trending on Trakt — In Your Library","Popular on Trakt — In Your Library","Recently Watched","Because You Watched"};
 public static final class Row {public String id,name;public boolean visible=true;public final Set<String> members=new LinkedHashSet<>();Row(String id,String name){this.id=id;this.name=name;}public boolean custom(){return id.startsWith("custom:");}}
 private final Context context;private final SharedPreferences prefs;public final List<Row> rows=new ArrayList<>();
 public PreviewHomeRows(Context c){context=c;prefs=androidx.preference.PreferenceManager.getDefaultSharedPreferences(c);try{JSONArray data=new JSONArray(prefs.getString("preview_home_rows41","[]"));for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);Row r=new Row(o.getString("id"),o.getString("name"));r.visible=o.optBoolean("visible",true);JSONArray members=o.optJSONArray("members");if(members!=null)for(int j=0;j<members.length();j++)r.members.add(members.getString(j));rows.add(r);}}catch(JSONException ignored){}for(int i=0;i<SYSTEM.length;i++){final String id=SYSTEM[i];if(rows.stream().noneMatch(r->r.id.equals(id)))rows.add(new Row(id,LABELS[i]));}}
 private void save(){JSONArray data=new JSONArray();try{for(Row r:rows)data.put(new JSONObject().put("id",r.id).put("name",r.name).put("visible",r.visible).put("members",new JSONArray(r.members)));prefs.edit().putString("preview_home_rows41",data.toString()).apply();}catch(JSONException error){throw new IllegalStateException(error);}}
 public List<Entry> members(Row row,Snapshot snapshot){List<Entry> result=new ArrayList<>();for(String key:row.members){for(Entry e:snapshot.movies)if(e.key().equals(key)){result.add(e);break;}for(Entry e:snapshot.shows)if(e.key().equals(key)){result.add(e);break;}}return result;}
 public boolean dismissed(Entry e){return prefs.contains("preview_cw_dismiss:"+e.key())&&e.playedAt<=prefs.getLong("preview_cw_dismiss:"+e.key(),0);}
 public void dismiss(Entry e){prefs.edit().putLong("preview_cw_dismiss:"+e.key(),e.playedAt).apply();}
 public static void add(Context c,Entry e,Runnable changed){if(e==null)return;PreviewHomeRows model=new PreviewHomeRows(c);List<Row> choices=new ArrayList<>();for(Row r:model.rows)if(r.custom()||r.id.equals("watchnext"))choices.add(r);List<String> labels=new ArrayList<>();for(Row r:choices)labels.add((r.members.contains(e.key())?"Remove from ":"Add to ")+r.name);labels.add("Create new row…");PreviewDialog.choose(c,"Add to Row",labels.toArray(new String[0]),-1,n->{if(n==choices.size())model.name("Create new row","",name->{Row row=new Row("custom:"+UUID.randomUUID(),name);row.members.add(e.key());model.rows.add(row);model.save();changed.run();});else{Row row=choices.get(n);boolean removed=!row.members.add(e.key());if(removed)row.members.remove(e.key());model.save();PreviewNotice.show(c,(removed?"Removed from ":"Added to ")+row.name,false);changed.run();}});}
 private void name(String title,String previous,java.util.function.Consumer<String> accept){EditText input=new EditText(context);input.setSingleLine(true);input.setText(previous);input.setHint("Row name");input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});AlertDialog d=new AlertDialog.Builder(context).setTitle(title).setView(input).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->{PreviewDialog.styleNative(d);d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{String value=input.getText().toString().trim();if(value.isEmpty()){input.setError("Enter a row name");return;}accept.accept(value);d.dismiss();});input.requestFocus();d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);});d.show();}
 public static void clearWatchNext(Context c){PreviewDialog.choose(c,"Remove all titles from Watch Next?",new String[]{"Cancel","Clear"},0,n->{if(n==1){PreviewHomeRows model=new PreviewHomeRows(c);for(Row row:model.rows)if(row.id.equals("watchnext"))row.members.clear();model.save();PreviewNotice.show(c,"Watch Next cleared",false);}});}
 public static void customise(Context c,Runnable changed){new PreviewHomeRows(c).editor(changed);}
 private void editor(Runnable changed){Dialog dialog=new Dialog(context);LinearLayout screen=new LinearLayout(context);screen.setOrientation(LinearLayout.VERTICAL);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);screen.setPadding(dp(20),dp(16),dp(20),dp(16));screen.setBackground(PreviewDialog.surface(context,false));TextView heading=label("Customise Home",21);screen.addView(heading);TextView help=label("Select a row to move it. Up / Down reorders; Select confirms. Hidden rows keep their titles.",13);help.setPadding(0,dp(8),0,dp(16));screen.addView(help);ScrollView scroll=new ScrollView(context);LinearLayout list=new LinearLayout(context);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);screen.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));final String[] moving={null};final Runnable[] render={null};render[0]=()->{list.removeAllViews();for(Row row:rows){LinearLayout line=new LinearLayout(context);TextView move=control((row.id.equals(moving[0])?"↕  ":"")+row.name,()->{moving[0]=row.id.equals(moving[0])?null:row.id;save();render[0].run();View target=list.findViewWithTag(row.id);if(target!=null)target.requestFocus();});move.setTag(row.id);move.setOnKeyListener((v,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN||!row.id.equals(moving[0])||key!=KeyEvent.KEYCODE_DPAD_UP&&key!=KeyEvent.KEYCODE_DPAD_DOWN)return false;int index=rows.indexOf(row),next=index+(key==KeyEvent.KEYCODE_DPAD_UP?-1:1);if(next>=0&&next<rows.size()){Collections.swap(rows,index,next);save();render[0].run();list.findViewWithTag(row.id).requestFocus();}return true;});line.addView(move,new LinearLayout.LayoutParams(0,dp(44),1));TextView visible=control(row.visible?"Shown":"Hidden",()->{row.visible=!row.visible;save();render[0].run();list.findViewWithTag(row.id+":visibility").requestFocus();});visible.setTag(row.id+":visibility");line.addView(visible,new LinearLayout.LayoutParams(dp(95),dp(44)));if(row.custom()){TextView more=control("More",()->PreviewDialog.choose(context,row.name,new String[]{"Rename","Delete row"},-1,n->{if(n==0)name("Rename row",row.name,value->{row.name=value;save();render[0].run();});else PreviewDialog.choose(context,"Delete row? Titles remain in your library",new String[]{"Cancel","Delete row"},0,answer->{if(answer==1){rows.remove(row);save();render[0].run();}});}));line.addView(more,new LinearLayout.LayoutParams(dp(82),dp(44)));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(5);list.addView(line,lp);}list.addView(control("Create new row…",()->name("Create new row","",name->{rows.add(new Row("custom:"+UUID.randomUUID(),name));save();render[0].run();})),new LinearLayout.LayoutParams(-1,dp(44)));};render[0].run();dialog.setContentView(screen);dialog.setOnDismissListener(d->changed.run());dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.4f);dialog.getWindow().setLayout(Math.min(dp(620),context.getResources().getDisplayMetrics().widthPixels-dp(60)),Math.min(dp(410),context.getResources().getDisplayMetrics().heightPixels-dp(60)));if(!rows.isEmpty())list.findViewWithTag(rows.get(0).id).requestFocus();}
 private TextView label(String text,int size){TextView v=new TextView(context);v.setText(text);v.setTextSize(size);v.setTextColor(0xffd6e5ef);return v;}
 private TextView control(String text,Runnable action){TextView v=label(text,14);v.setGravity(Gravity.CENTER_VERTICAL);v.setPadding(dp(12),0,dp(12),0);v.setFocusable(true);v.setFocusableInTouchMode(true);v.setBackground(PreviewDialog.focus(context));v.setOnClickListener(w->action.run());return v;}
 private int dp(int n){return PreviewDialog.dp(context,n);}
}
